import re


_LINE_RE = re.compile(
    r"JOB\s+(?P<name>\S+)\s+AT\s+(?P<at>\d{2}:\d{2})\s+"
    r"RUN\s+(?P<script>\S+)"
    r"(?:\s+ON_ERROR\s+(?P<on_error>ABORT|CONTINUE|RETRY:\d+))?"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse Meridian CRM 4.2 batch_jobs.cfg content in file order."""
    schedule: list[dict] = []

    for line_number, line in enumerate(cfg_text.splitlines(), start=1):
        if not line.strip() or line.startswith("#"):
            continue

        match = _LINE_RE.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid batch job line {line_number}: {line!r}")

        hour, minute = map(int, match["at"].split(":"))
        if hour > 23 or minute > 59:
            raise ValueError(f"Invalid job time on line {line_number}: {match['at']!r}")

        clause = match["on_error"]
        if clause is None or clause == "ABORT":
            on_error = {"policy": "ABORT", "retries": 0}
        elif clause == "CONTINUE":
            on_error = {"policy": "CONTINUE", "retries": 0}
        else:
            on_error = {"policy": "RETRY", "retries": int(clause.split(":", 1)[1])}

        schedule.append(
            {
                "name": match["name"],
                "at": match["at"],
                "script": match["script"],
                "on_error": on_error,
            }
        )

    return schedule
